import{_ as r,c as e,o,ae as t}from"./chunks/framework.CliRSA9F.js";const i="/images/show_rankings.webp",p=JSON.parse('{"title":"Show Rankings","description":"","frontmatter":{},"headers":[],"relativePath":"features/show-rankings.md","filePath":"features/show-rankings.md"}'),n={name:"features/show-rankings.md"};function s(l,a,d,h,g,u){return o(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="show-rankings" tabindex="-1">Show Rankings <a class="header-anchor" href="#show-rankings" aria-label="Permalink to &quot;Show Rankings&quot;">​</a></h1><h2 id="track-your-keyword-rankings-across-all-platforms" tabindex="-1">Track Your Keyword Rankings Across All Platforms <a class="header-anchor" href="#track-your-keyword-rankings-across-all-platforms" aria-label="Permalink to &quot;Track Your Keyword Rankings Across All Platforms&quot;">​</a></h2><p>Show Rankings lets you monitor how your podcast ranks for specific keywords across Apple Podcasts, Spotify, Amazon Music, and YouTube Music. Add keywords to track, organize them into groups, and watch your rankings improve over time.</p><p>If you&#39;ve searched for &quot;Platform Rankings,&quot; this is the same feature—that&#39;s the page&#39;s browser tab title. Throughout PodSEO it&#39;s called Show Rankings.</p><p><img src="'+i+'" alt="Show Rankings Dashboard" width="600px" style="display:block;margin:0 auto;"></p><h2 id="what-you-ll-see" tabindex="-1">What You&#39;ll See <a class="header-anchor" href="#what-you-ll-see" aria-label="Permalink to &quot;What You&#39;ll See&quot;">​</a></h2><h3 id="multi-platform-ranking-table" tabindex="-1">Multi-Platform Ranking Table <a class="header-anchor" href="#multi-platform-ranking-table" aria-label="Permalink to &quot;Multi-Platform Ranking Table&quot;">​</a></h3><p>The main view shows your tracked keywords with rankings for each platform:</p><ul><li><strong>Keyword</strong> - The search term you&#39;re tracking</li><li><strong>Best Rank</strong> - Your highest ranking across all platforms</li><li><strong>Apple Podcasts (AP)</strong> - Current rank and change indicator</li><li><strong>Spotify (SP)</strong> - Current rank and change indicator</li><li><strong>Amazon Music (AM)</strong> - Current rank and change indicator</li><li><strong>YouTube Music (YM)</strong> - Current rank and change indicator</li></ul><p>Each platform column shows:</p><ul><li>Your current position (e.g., #8)</li><li>Change since last check (e.g., +3 or -2)</li><li>Blank if not ranking for that keyword</li></ul><h3 id="ranking-chart" tabindex="-1">Ranking Chart <a class="header-anchor" href="#ranking-chart" aria-label="Permalink to &quot;Ranking Chart&quot;">​</a></h3><p>Above the table, a line chart shows ranking history for the selected platform. Toggle between platforms to see trends over your chosen timeframe.</p><h3 id="smart-groups" tabindex="-1">Smart Groups <a class="header-anchor" href="#smart-groups" aria-label="Permalink to &quot;Smart Groups&quot;">​</a></h3><p>Quick filters to find keywords by performance:</p><ul><li><strong>All Keywords</strong> - Your complete tracking list</li><li><strong>Top 10 Rankings</strong> - Keywords where you rank in the top 10</li><li><strong>Rising Fast</strong> - Keywords with improving rankings</li><li><strong>Dropping Fast</strong> - Keywords losing positions</li><li><strong>New (7 days)</strong> - Recently added keywords</li><li><strong>Not Ranking</strong> - Keywords where you don&#39;t appear in results</li></ul><h3 id="custom-groups" tabindex="-1">Custom Groups <a class="header-anchor" href="#custom-groups" aria-label="Permalink to &quot;Custom Groups&quot;">​</a></h3><p>Create your own keyword groups to organize tracking by topic, campaign, or priority. Custom groups appear in the sidebar alongside Smart Groups, each with a color dot for quick identification.</p><h2 id="managing-your-keywords" tabindex="-1">Managing Your Keywords <a class="header-anchor" href="#managing-your-keywords" aria-label="Permalink to &quot;Managing Your Keywords&quot;">​</a></h2><h3 id="adding-keywords" tabindex="-1">Adding Keywords <a class="header-anchor" href="#adding-keywords" aria-label="Permalink to &quot;Adding Keywords&quot;">​</a></h3><p>Add new keywords to track using the add form. Consider tracking:</p><ul><li>Your primary positioning keywords</li><li>Competitor keywords you want to rank for</li><li>Topic keywords in your niche</li><li>Branded terms (your podcast name, host names)</li></ul><h3 id="creating-and-using-groups" tabindex="-1">Creating and Using Groups <a class="header-anchor" href="#creating-and-using-groups" aria-label="Permalink to &quot;Creating and Using Groups&quot;">​</a></h3><p>To create a custom group:</p><ol><li>Click <strong>Create Group</strong> in the sidebar</li><li>Choose a name and a color for the group</li><li>Click <strong>Save</strong> to add it to your sidebar</li></ol><p>To assign keywords to a group, use the group dropdown on any keyword row in the table — select which groups the keyword belongs to. A keyword can belong to multiple groups.</p><p>Once created, click any group in the sidebar (desktop) or the group chips (mobile) to filter the table and chart to just those keywords.</p><h3 id="timeframe-selection" tabindex="-1">Timeframe Selection <a class="header-anchor" href="#timeframe-selection" aria-label="Permalink to &quot;Timeframe Selection&quot;">​</a></h3><p>Choose how much history to display:</p><ul><li><strong>15 days</strong> - Recent performance</li><li><strong>30 days</strong> - Monthly view</li><li><strong>90 days</strong> - Quarterly trends</li></ul><h3 id="exporting-data" tabindex="-1">Exporting Data <a class="header-anchor" href="#exporting-data" aria-label="Permalink to &quot;Exporting Data&quot;">​</a></h3><p>Download your keyword data as CSV for external analysis or reporting.</p><h2 id="understanding-your-rankings" tabindex="-1">Understanding Your Rankings <a class="header-anchor" href="#understanding-your-rankings" aria-label="Permalink to &quot;Understanding Your Rankings&quot;">​</a></h2><h3 id="reading-the-delta" tabindex="-1">Reading the Delta <a class="header-anchor" href="#reading-the-delta" aria-label="Permalink to &quot;Reading the Delta&quot;">​</a></h3><p>The change indicator shows movement since the previous data point:</p><ul><li><strong>Green (+)</strong> - Ranking improved (moved up)</li><li><strong>Red (-)</strong> - Ranking dropped (moved down)</li><li><strong>No indicator</strong> - Position unchanged</li></ul><h3 id="platform-differences" tabindex="-1">Platform Differences <a class="header-anchor" href="#platform-differences" aria-label="Permalink to &quot;Platform Differences&quot;">​</a></h3><p>Rankings often vary by platform:</p><ul><li>A keyword ranking #5 on Apple might be #15 on Spotify</li><li>Some platforms may not rank your podcast for certain keywords</li><li>Focus optimization where you have the most potential</li></ul><h3 id="smart-group-insights" tabindex="-1">Smart Group Insights <a class="header-anchor" href="#smart-group-insights" aria-label="Permalink to &quot;Smart Group Insights&quot;">​</a></h3><p>Use smart groups to prioritize efforts:</p><ul><li><strong>Top 10</strong> - Maintain and protect these positions</li><li><strong>Rising Fast</strong> - Momentum to capitalize on</li><li><strong>Dropping Fast</strong> - May need attention</li><li><strong>Not Ranking</strong> - Opportunities or unrealistic targets</li></ul><h2 id="strategic-use" tabindex="-1">Strategic Use <a class="header-anchor" href="#strategic-use" aria-label="Permalink to &quot;Strategic Use&quot;">​</a></h2><h3 id="prioritizing-optimization" tabindex="-1">Prioritizing Optimization <a class="header-anchor" href="#prioritizing-optimization" aria-label="Permalink to &quot;Prioritizing Optimization&quot;">​</a></h3><p>Focus energy where it matters:</p><ul><li><strong>Near top 10</strong> - Small improvements here have big impact</li><li><strong>Rising keywords</strong> - Ride momentum with content reinforcement</li><li><strong>Dropping keywords</strong> - Investigate causes before they fall further</li></ul><h3 id="correlating-with-content" tabindex="-1">Correlating with Content <a class="header-anchor" href="#correlating-with-content" aria-label="Permalink to &quot;Correlating with Content&quot;">​</a></h3><p>Connect rankings to content:</p><ul><li>Did a specific episode boost certain keywords?</li><li>Do ranking changes correlate with publishing frequency?</li><li>Which topics drive the best keyword performance?</li></ul><h3 id="competitive-tracking" tabindex="-1">Competitive Tracking <a class="header-anchor" href="#competitive-tracking" aria-label="Permalink to &quot;Competitive Tracking&quot;">​</a></h3><p>Add competitor-relevant keywords to understand:</p><ul><li>Keywords where competitors rank but you don&#39;t</li><li>Gaps in your keyword coverage</li><li>Opportunities to differentiate</li></ul><h2 id="integration-with-other-features" tabindex="-1">Integration with Other Features <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;Integration with Other Features&quot;">​</a></h2><ul><li><strong>Keyword Strategy</strong> - Keywords from your strategy appear here</li><li><strong>Show Visibility</strong> - Discover keywords you rank for organically</li><li><strong>Keyword Tracker</strong> - Alternative view focused on individual keyword history</li></ul><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Show Rankings is available to Pro subscribers. Free users see a limited preview with sample keywords.</p><p><strong>Related Features</strong>: Use <a href="/features/keyword-strategy.html">Keyword Strategy</a> to build your keyword plan, <a href="/features/show-visibility.html">Show Visibility</a> to discover organic rankings, and <a href="/features/episode-rankings.html">Episode Rankings</a> for episode-level tracking.</p>',57)])])}const m=r(n,[["render",s]]);export{p as __pageData,m as default};
